div.script:
var RPC = function(model, method, kwargs) {
    return fetch("/web/dataset/call_kw", {
        method: "POST",
        headers: {"Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest"},
        body: JSON.stringify({jsonrpc: "2.0", method: "call",
            params: {model: model, method: method, args: [], kwargs: kwargs || {}}}),
    }).then(function(r) { return r.json(); }).then(function(j) {
        if (j.error) { throw new Error((j.error.data && j.error.data.message) || j.error.message); }
        return j.result;
    });
};
var root = document.getElementById("odk-bscan-root");
var state = root.querySelector("#state");
var logBox = root.querySelector("#log");
var logCount = 0;
var current = null;
var setState = function(t, cls) { state.textContent = t; state.className = "pill " + (cls || "err"); };
var esc = function(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, function(c) {
    return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]; }); };

RPC("odk.dispatch.barcode", "act_warehouses", {}).then(function(ws) {
    var sel = root.querySelector("#wh-sel");
    sel.innerHTML = "";
    ws.forEach(function(w) {
        var o = document.createElement("option");
        o.value = w.id; o.textContent = w.name + " (" + w.code + ")";
        sel.appendChild(o);
    });
}).catch(function(e) { setState("仓库加载失败：" + e.message); });

var doLookup = function(code) {
    setState("识别中…");
    RPC("odk.dispatch.barcode", "act_lookup_barcode", {code: code}).then(function(item) {
        if (!item || !item.kind) {
            setState("未识别", "err");
            current = null;
            root.querySelector("#item-box").style.display = "none";
            root.querySelector("#action-box").style.display = "none";
            return;
        }
        current = item; current.scanned = code;
        root.querySelector("#item-box").style.display = "block";
        if (item.kind === "merge") {
            setState("套码已识别（" + item.members.length + " 张部件）", "ok");
            var rows = item.members.map(function(m) {
                return "<tr><td>" + esc(m.barcode) + "</td><td>" + esc(m.dispatch) +
                    "</td><td>" + esc(m.product) + "</td><td>" + m.qty + "</td></tr>";
            }).join("");
            root.querySelector("#item-info").innerHTML =
                "<b>套码 " + esc(item.barcode) + "</b>" +
                "<table><tr><th>部件条码</th><th>派工单</th><th>部件</th><th>数量</th></tr>" + rows + "</table>";
            root.querySelector("#action-box").style.display = "block";
            root.querySelector("#btn-in").style.display = "none";
            root.querySelector("#btn-out").style.display = "none";
        } else {
            setState("部件条码已识别", "ok");
            root.querySelector("#item-info").innerHTML =
                "<b>" + esc(item.barcode) + "</b> · 每张数量 " + item.qty + "<br/>" +
                "派工单：<b>" + esc(item.dispatch) + "</b>（" + esc(item.dispatch_type) +
                " · " + esc(item.operation) + " · " + esc(item.state) + "）<br/>" +
                "部件：" + esc(item.product) + " · 历史扫码 " + item.scans + " 次";
            root.querySelector("#action-box").style.display = "block";
            root.querySelector("#btn-in").style.display = "";
            root.querySelector("#btn-out").style.display = "";
        }
    }).catch(function(e) { setState("识别失败：" + e.message); });
};

root.querySelector("#scan-input").addEventListener("keydown", function(ev) {
    if (ev.key !== "Enter") return;
    var code = ev.target.value.trim();
    if (!code) return;
    doLookup(code);
});

var addLog = function(html) {
    logCount++;
    if (logCount === 1) logBox.innerHTML = "";
    var row = document.createElement("div");
    row.className = "log";
    row.innerHTML = html;
    logBox.insertBefore(row, logBox.firstChild);
};

var register = function(action) {
    if (!current) return;
    var qty = parseFloat(root.querySelector("#qty").value || "0");
    var whId = root.querySelector("#wh-sel").value;
    var btn = this;
    btn.disabled = true;
    RPC("odk.dispatch.barcode", "act_register", {
        code: current.scanned, action: action, qty: qty, warehouse_id: parseInt(whId), note: "",
    }).then(function(res) {
        addLog("<b>" + esc(current.scanned) + "</b> " + esc(res.message || "") +
               (res.wms ? " · " + esc(res.wms) : ""));
        setState(res.message || "完成", "ok");
        var si = root.querySelector("#scan-input");
        si.value = ""; si.focus();
        if (current.kind === "merge") {
            root.querySelector("#btn-in").style.display = "";
            root.querySelector("#btn-out").style.display = "";
        }
    }).catch(function(e) { setState("失败：" + e.message); })
    .then(function() { btn.disabled = false; });
};

root.querySelector("#btn-in").addEventListener("click", register.bind(root.querySelector("#btn-in"), "in"));
root.querySelector("#btn-out").addEventListener("click", register.bind(root.querySelector("#btn-out"), "out"));
root.querySelector("#btn-query").addEventListener("click", register.bind(root.querySelector("#btn-query"), "lookup"));
root.querySelector("#scan-input").focus();
